    static void antibanding(MainActivity a){a.openUtility(new UtilitySheet(a,"灯光防频闪",s->{s.note("自动检测灯光频率。室内灯光下仍忽明忽暗时，可选择与当地电源一致的50Hz或60Hz；不会重启镜头。");s.options(new String[]{"自动","50Hz","60Hz"},FlickerControl.safe(a.prefs.getInt("antibanding",0)),id->{a.prefs.edit().putInt("antibanding",id).apply();a.camera.antibanding(id);});s.status(a.camera::antibandingStatus);s.note("仅请求当前镜头支持的模式；部分LED和屏幕使用独立调光频率，实际效果取决于灯具和相机接口。");}));}
