    static void metering(MainActivity a){if(a.busy){a.toast("请等待本次拍摄完成");return;}a.finderTouch.cancel();a.openUtility(new UtilitySheet(a,"测光方式",s->{s.note("轻点画面对焦，EV 归零，保留当前测光方式。仅点测光模式在对焦框内显示青绿 AE 圆环；拖动圆环可从框中分离测光点，保留对焦和 EV。测光位置持续有效，曝光随该处光线自动变化；长按才锁定曝光。");s.status(a.camera::meteringStatus);String[] labels={"全局自动 · 系统默认","中央区域 · 画面中央 50%","点测光 · 最后点位 / 中心"};for(int i=0;i<3;i++){final int mode=i;android.widget.TextView option=s.action(labels[i]+(a.camera.points().mode==i?" ✓":""),()->{if(!a.busy){a.camera.meteringMode(mode);s.dismiss();}});option.setEnabled(!a.busy&&(i==0||!a.camera.areaMeteringKnown()||a.camera.areaMeteringSupported()));}s.note("中央与点测光使用原生 AE 区域、权重 1000；实际响应由相机决定。切换真实镜头、画幅或离开取景会清除点位，点测光从中心开始。");}).previewVisible());}
