    static void composition(MainActivity a){a.openUtility(new UtilitySheet(a,"构图辅助",s->{s.note("在设置中调整构图辅助。辅助标记只显示在取景中，不写入照片。");s.toggle("显示构图辅助",a.composition.on,on->{a.composition.on=on;a.saveComposition();});s.toggle("水平仪",a.composition.level,on->{a.composition.level=on;a.saveComposition();});s.toggle("中央十字",a.composition.cross,on->{a.composition.cross=on;a.saveComposition();});s.section("构图线");s.options(new String[]{"无","九宫格","黄金分割","对角线"},a.composition.lines,id->{a.composition.lines=id;a.saveComposition();});s.note(a.levels!=null&&a.levels.available()?"水平仪随实际横竖持机方向调整，手机接近平放时隐藏。":"此设备没有可用的水平仪传感器。");}));}static void preview(MainActivity a){a.openUtility(new UtilitySheet(a,"预览质量",s->{s.note("清晰优先为长焦保留更多源细节；流畅优先降低预览预算，拍照输出独立。只使用当前光学镜头公开的尺寸，配置失败会回退。");s.choices(new String[]{"清晰优先","流畅优先"},a.prefs.getInt("preview_mode",0),id->{a.prefs.edit().putInt("preview_mode",id).apply();a.camera.quality(id);});}));}
    static void quality(MainActivity a){a.openUtility(new UtilitySheet(a,"画面与胶片",s->{s.slider("肤色保护",0,1,a.settings.skin,v->{a.settings.skin=v;a.syncFilm();});s.slider("高光柔化",0,1,a.settings.highlights,v->{a.settings.highlights=v;a.syncFilm();});s.toggle("自适应轻颗粒",a.settings.adaptiveGrain,on->{a.settings.adaptiveGrain=on;a.syncFilm();});s.note("肤色保护使用暖色区域软混合，不是人脸识别；高光柔化不能恢复已过曝的原始细节。高ISO、暗部和较小输出会减少额外模拟颗粒。");s.action("胶片强度 · "+FilmStrength.percent(a.settings.strength)+"%",()->{s.dismiss();a.showStrength();});s.action("恢复画质默认值",()->{a.settings.skin=.25f;a.settings.highlights=.25f;a.settings.adaptiveGrain=true;a.syncFilm();s.dismiss();});}));}
    static void calibration(MainActivity a,int base){if(a.page!=0)a.switchPage(0);final CalibrationSample[] sample={null};UtilitySheet sheet=new UtilitySheet(a,base+"mm 镜头校准",s->{s.note("当前取景 "+(int)a.focal+"mm，编辑 "+base+"mm 校准。\n各镜头独立保存，默认中性；需用同一光线下的灰卡实拍校准。未完成真机标定前不会套用猜测偏色。");s.choices(new String[]{"14mm","23mm","85mm"},base==14?0:base==23?1:2,id->{int mm=new int[]{14,23,85}[id];if(a.camera.available(mm))a.selectFocal(mm);a.main.post(()->calibration(a,mm));});
            for(int c=0;c<3;c++){final int channel=c;String key="cal_"+base+"_"+c;s.slider(new String[]{"红通道","绿通道","蓝通道"}[c],.85f,1.15f,a.prefs.getFloat(key,1),v->{a.prefs.edit().putFloat(key,v).apply();a.syncFilm();});}
            s.slider("反差",.9f,1.1f,a.prefs.getFloat("cal_"+base+"_contrast",1),v->{a.prefs.edit().putFloat("cal_"+base+"_contrast",v).apply();a.syncFilm();});s.slider("亮度补偿 EV",-.5f,.5f,a.prefs.getFloat("cal_"+base+"_ev",0),v->{a.prefs.edit().putFloat("cal_"+base+"_ev",v).apply();a.syncFilm();});
            TextView button=s.action("中央灰卡取样",()->{if(LensPlan.base(a.focal)!=base||!a.camera.available(base)){a.toast("请先切换到该镜头并等待取景就绪");return;}if(sample[0]!=null){a.toast("正在取样");return;}sample[0]=new CalibrationSample(a.camera,(rgb,error)->{sample[0]=null;if(!s.isShowing()||!a.resumed)return;if(rgb==null){a.toast(error);return;}android.content.SharedPreferences.Editor edit=a.prefs.edit();for(int i=0;i<3;i++)edit.putFloat("cal_"+base+"_"+i,rgb[i]);edit.apply();a.syncFilm();a.toast("已保存灰卡校准；请用相同场景与主摄对比");s.dismiss();});});button.setEnabled(a.camera.available(base));s.action("重置该镜头",()->{android.content.SharedPreferences.Editor edit=a.prefs.edit();for(int i=0;i<3;i++)edit.remove("cal_"+base+"_"+i);edit.remove("cal_"+base+"_contrast").remove("cal_"+base+"_ev").apply();a.syncFilm();s.dismiss();});});a.openUtility(sheet);sheet.setOnDismissListener(d->{if(sample[0]!=null)sample[0].cancel();if(a.activeUtility==sheet)a.activeUtility=null;});}
    static void saveRecipe(MainActivity a){EditText name=new EditText(a);name.setSingleLine(true);name.setTextColor(CREAM);name.setHint("例如：周末暖调");name.setHintTextColor(MUTED);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(32)});AlertDialog dialog=new AlertDialog.Builder(a,ThemeUi.alertTheme()).setTitle("保存当前配方").setView(name).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{new RecipeStore(a.getFilesDir()).add(name.getText().toString(),a.settings);a.toast("配方已保存");dialog.dismiss();}catch(Exception e){name.setError(e.getMessage());}}));dialog.show();}
    static void recipes(MainActivity a){a.openUtility(new UtilitySheet(a,"我的配方",s->{s.action("保存当前配方",()->saveRecipe(a));LinearLayout transfers=a.row();a.weight(transfers,a.button("导入 JSON",()->a.recipeDocument(false)),48);a.weight(transfers,a.button("导出配方库",()->a.recipeDocument(true)),48);a.add(s.content,transfers,-1,48);s.note("最多50份，包含基础胶片、色彩、强度和画质设置；镜头校准与拍摄ISO不会随配方覆盖。");try{List<RecipeStore.Recipe> all=new RecipeStore(a.getFilesDir()).list();if(all.isEmpty())s.note("还没有配方，调整画面后即可保存。");for(RecipeStore.Recipe r:all){LinearLayout row=a.row();TextView use=a.button(r.name+" · "+FilmCatalog.reelName(r.settings.stock),()->{a.settings=r.settings.copy();a.setStock(a.settings.stock);a.refreshRoomControls();a.syncFilm();s.dismiss();});row.addView(use,new LinearLayout.LayoutParams(0,a.dp(52),1));a.add(row,a.button("删除",()->new AlertDialog.Builder(a,ThemeUi.alertTheme()).setTitle("删除配方？").setMessage(r.name).setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{try{new RecipeStore(a.getFilesDir()).remove(r.id);s.dismiss();recipes(a);}catch(Exception e){a.toast(e.getMessage());}}).show()),60,52);a.add(s.content,row,-1,52);a.gap(s.content,6);}}catch(Exception e){s.note("无法读取配方："+e.getMessage());}}));}
    static void trash(MainActivity a){NegativeTrash.recover(a.rollDir,System.currentTimeMillis());a.openUtility(new UtilitySheet(a,"回收站 · 保留7天",s->{List<String> ids=NegativeTrash.list(a.rollDir);s.note("恢复后回到底片列表。永久删除会清除内部原片、成片、参数及DNG，系统相册副本保留。");for(String id:ids){s.note(id+" · "+remaining(a,id));LinearLayout row=a.row();a.weight(row,a.button("恢复",()->recycle(a,s,id,true)),48);a.weight(row,a.button("永久删除",()->new AlertDialog.Builder(a,ThemeUi.alertTheme()).setTitle("永久删除此底片？").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->recycle(a,s,id,false)).show()),48);a.add(s.content,row,-1,48);}if(ids.isEmpty())s.note("回收站为空");else s.action("清空回收站",()->new AlertDialog.Builder(a,ThemeUi.alertTheme()).setTitle("永久删除回收站全部底片？").setMessage(ids.size()+"张，无法撤销").setNegativeButton("取消",null).setPositiveButton("清空",(d,w)->{s.dismiss();a.worker.execute(()->{int count=0;for(String id:ids)try{NegativeTrash.erase(a.rollDir,id);count++;}catch(Exception ignored){}int done=count;a.main.post(()->{a.toast("已清理 "+done+" 张");trash(a);});});}).show());}));}
    private static String remaining(MainActivity a,String id){try{long ms=NegativeTrash.RETENTION-(System.currentTimeMillis()-NegativeTrash.deletedAt(a.rollDir,id));return "剩余 "+Math.max(1,(ms+86399999)/86400000)+" 天";}catch(Exception e){return "删除记录待检查";}}
    private static void recycle(MainActivity a,UtilitySheet s,String id,boolean restore){s.dismiss();a.worker.execute(()->{String result;try{if(restore)NegativeTrash.restore(a.rollDir,id);else NegativeTrash.erase(a.rollDir,id);result=restore?"底片已恢复":"已永久删除";}catch(Exception e){result=e.getMessage();}String message=result;a.main.post(()->{a.toast(message);if(a.page==2)a.refreshGallery();a.refreshLatest();trash(a);});});}
